package com.meetspace.service; import com.meetspace.cache.RoomIndex; import com.meetspace.dto.RoomDtos.*; import com.meetspace.exception.ApiException; import com.meetspace.repository.RoomRepository; import org.springframework.dao.DuplicateKeyException; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class RoomService{private final RoomRepository r;private final RoomIndex index;public RoomService(RoomRepository r,RoomIndex i){this.r=r;index=i;}public List<Room> list(){var rooms=r.active();rooms.forEach(index::put);return rooms;}public Room get(UUID id){return index.get(id).filter(Room::active).orElseGet(()->{var room=r.byId(id,false).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"ROOM_NOT_FOUND","Room was not found"));index.put(room);return room;});}@Transactional public Room create(Save x){try{var room=r.byId(r.create(x),true).orElseThrow();index.put(room);return room;}catch(DuplicateKeyException e){throw new ApiException(HttpStatus.CONFLICT,"ROOM_CODE_EXISTS","Room code already exists");}}@Transactional public Room update(UUID id,Save x){try{if(!r.update(id,x))throw new ApiException(HttpStatus.NOT_FOUND,"ROOM_NOT_FOUND","Room was not found");var room=r.byId(id,true).orElseThrow();index.put(room);return room;}catch(DuplicateKeyException e){throw new ApiException(HttpStatus.CONFLICT,"ROOM_CODE_EXISTS","Room code already exists");}}public void deactivate(UUID id){if(!r.deactivate(id))throw new ApiException(HttpStatus.NOT_FOUND,"ROOM_NOT_FOUND","Active room was not found");r.byId(id,true).ifPresent(index::put);}}